final _itemAssetPattern = RegExp(r'^assets/icons/(?:items|buffs)/(\d+)\.webp$');

int? _itemId(String path) {
  final match = _itemAssetPattern.firstMatch(path);
  return match == null ? null : int.tryParse(match.group(1)!);
}

int? gatheringItemGrade(String path) => gatheringItemGrades[_itemId(path)];

String gatheringItemArtwork(String path) {
  final id = _itemId(path);
  return gatheringItemGrades.containsKey(id)
      ? 'assets/icons/item_artwork/$id.webp'
      : path;
}
